import {people} from './data.js';
const themes=['Identity continuity','First-day readiness','Remote onboarding','Shared-device access','Access governance','Offboarding evidence'];
export function homePage(){return `<div class="home-shell"><header class="home-header"><a href="#home" aria-label="MajorKey workshop home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="180" height="32"></a><span>IDENTITY IN ACTION</span><button class="quiet" data-action="agenda">Workshop agenda ↗</button></header><main class="home-main"><section class="home-intro"><div><div class="eyebrow">HARBORLINE · A DAY IN THE LIFE</div><h1>Start with a person.<br><span>See identity in action.</span></h1><p>Follow their working day, understand the architecture, then bring it to life in your tenant.</p></div><ol class="home-route" aria-label="Workshop journey"><li class="current"><b>01</b><span>Choose a persona<small>Whose day will you follow?</small></span></li><li><b>02</b><span>The story<small>Understand the human need</small></span></li><li><b>03</b><span>Architecture<small>See how the controls connect</small></span></li><li><b>04</b><span>Live demo<small>Explore both sides in the lab</small></span></li></ol></section><div class="home-section-heading"><h2>Choose your persona</h2><span>6 people · 22 moments · one connected workshop</span></div><section class="home-personas" aria-label="Choose a persona">${people.map((p,i)=>`<button class="home-persona" data-action="person" data-value="${i}" style="--persona-tone:${['#20f593','#c398ff','#77ddcb','#b9b1ff','#f0c994','#83c5ff'][i]}"><div class="home-card-top"><span class="home-avatar">${p.initials}</span><span class="home-topic">${themes[i]}</span><span class="home-card-arrow" aria-hidden="true">↗</span></div><h3>${p.name}</h3><div class="home-job">${p.job}</div><h4>${p.role}</h4><p>${p.intro}</p><div class="home-card-foot"><span>${p.moments.length} story moments</span><strong>Follow ${p.name.split(' ')[0]}’s day →</strong></div></button>`).join('')}</section><footer class="home-footer"><span>MajorKey · Harborline reference lab</span><div><button class="quiet" data-action="catalog">Browse 34 use cases</button><button class="quiet" data-action="ready">Presenter preparation</button></div></footer></main></div><dialog id="modal" aria-labelledby="modal-title"></dialog>`;}
